INSERT INTO message (id, session_id, time_created, time_updated, data) VALUES ('msg_0136', 'opencode-real-sanitized', 1786753841312, 1786753841312, '{"agent":"build","model":{"modelID":"gpt-5.6-luna","providerID":"local","variant":"max"},"role":"user","summary":{"diffs":[{"additions":20,"deletions":3,"file":"src/main.rs","patch":"Index: src/main.rs =================================================================== --- src/main.rs +++ src/main.rs @@ -1,252 +1,269 @@ use std::path::{Path, PathBuf}; +use std::io::Write; use clap::{Parser, Subcommand}; use migrate::config; use migrate::export; use migrate::import; use migrate::ir; use migrate::ir::AgentKind; use migrate::readers; use migrate::sync; use migrate::util; #[derive(Parser)] #[command(name = \"migrate\", about = \"Cross coding-agent execution history migration tool\", version)] struct Cli { #[command(subcommand)] command: Command, } #[derive(Subcommand)] enum Command { /// List available sessions of an agent List { agent: String, #[arg(long)] codex_root: Option<PathBuf>, #[arg(long)] pi_root: Option<PathBuf>, #[arg(long)] opencode_db: Option<PathBuf>, }, /// Read an agent session and export a portable seed (seed.json + seed.md + manifest.json) Export { agent: String, session: String, #[arg(short, long)] out: Option<PathBuf>, #[arg(long)] codex_root: Option<PathBuf>, #[arg(long)] pi_root: Option<PathBuf>, #[arg(long)] opencode_db: Option<PathBuf>, }, /// Import a seed into a target agent''s native storage Import { agent: String, #[arg(short, long)] seed: Option<PathBuf>, #[arg(long)] pi_root: Option<PathBuf>, #[arg(long)] opencode_db: Option<PathBuf>, }, /// Diff the seed''s source and target sessions against the manifest Status { seed: Option<PathBuf>, #[arg(long)] opencode_db: Option<PathBuf>, }, } fn main() { let cli = Cli::parse(); if let Err(e) = run(cli) { eprintln!(\"error: {e}\"); std::process::exit(1); } } fn default_codex_root() -> PathBuf { config::home_dir().join(\".codex/sessions\") } fn default_pi_root() -> PathBuf { config::home_dir().join(\".pi/agent/sessions\") } fn default_opencode_db() -> PathBuf { config::home_dir().join(\".local/share/opencode/opencode.db\") } fn run(cli: Cli) -> Result<(), String> { match cli.command { Command::List { agent, codex_root, pi_root, opencode_db } => { let kind = parse_agent(&agent)?; + let stdout =\n[TRUNCATED]","status":"modified"},{"additions":74,"deletions":0,"file":"tests/real_sessions.rs","patch":"Index: tests/real_sessions.rs =================================================================== --- tests/real_sessions.rs +++ tests/real_sessions.rs @@ -0,0 +1,74 @@ +use std::path::{Path, PathBuf}; + +use migrate::{config, import, readers}; + +#[test] +#[ignore = \"reads local agent histories; writes only temp copies / temp roots\"] +fn real_pi_and_opencode_sessions_smoke() { + let home = config::home_dir(); + let pi_root = home.join(\".pi/agent/sessions\"); + let opencode_db = std::env::var(\"MIGRATE_REAL_OPENCODE_DB\") + .map(PathBuf::from) + .unwrap_or_else(|_| home.join(\".local/share/opencode/opencode.db\")); + + let pi_path = pick_pi_session(&pi_root); + let tmp = std::env::temp_dir().join(format!(\"migrate-real-{}\", uuid::Uuid::new_v4().simple())); + std::fs::create_dir_all(&tmp).unwrap(); + + let pi_trace = readers::pi::read(&pi_path).expect(\"read real pi session\"); + assert!(pi_trace.events.len() > 5); + + let pi_to_pi = import::pi::import(&pi_trace, &tmp.join(\"pi-root\")).expect(\"pi -> pi\"); + let pi_back = readers::pi::read(Path::new(&pi_to_pi.file)).expect(\"read imported pi\"); + assert_eq!(pi_back.events.len(), pi_trace.events.len()); + assert_eq!(pi_back.meta.events_sha256, pi_trace.meta.events_sha256); + + let copied_db = tmp.join(\"opencode.db\"); + std::fs::copy(&opencode_db, &copied_db).expect(\"copy opencode db\"); + let pi_to_open = import::opencode::import(&pi_trace, &copied_db).expect(\"pi -> opencode copy\"); + let open_back = readers::opencode::read(&copied_db, &pi_to_open.session_id).expect(\"read imported opencode\"); + assert!(!open_back.events.is_empty()); + assert!(open_back.events.len() <= pi_trace.events.len()); + + let open_session = pick_opencode_session(&copied_db); + let open_trace = readers::opencode::read(&copied_db, &open_session).expect(\"read real opencode session\"); + assert!(open_trace.events.len() > 5); + let open_to_pi = import::pi::import(&open_trace, &tmp.join(\"pi-root2\")).expect(\"opencode -> pi\"); + let open_pi_back = readers::pi::read\n[TRUNCATED]","status":"added"}]},"time":{"created":1786753841312}}');
