INSERT INTO message (id, session_id, time_created, time_updated, data) VALUES ('msg_0148', 'opencode-real-sanitized', 1786756777572, 1786756777572, '{"agent":"build","model":{"modelID":"gpt-5.6-luna","providerID":"local","variant":"max"},"role":"user","summary":{"diffs":[{"additions":270,"deletions":0,"file":"src/bin/make_fixtures.rs","patch":"Index: src/bin/make_fixtures.rs =================================================================== --- src/bin/make_fixtures.rs +++ src/bin/make_fixtures.rs @@ -0,0 +1,270 @@ +use std::collections::HashMap; +use std::io::Write; +use std::path::{Path, PathBuf}; + +use migrate::{config, ir::EventKind, readers}; +use rusqlite::Connection; +use serde_json::{json, Value}; + +fn main() -> Result<(), String> { + let out = std::env::args() + .skip_while(|arg| arg != \"--out\") + .nth(1) + .map(PathBuf::from) + .unwrap_or_else(|| PathBuf::from(\"tests/fixtures/real\")); + std::fs::create_dir_all(&out).map_err(|e| format!(\"mkdir {}: {e}\", out.display()))?; + + let home = config::home_dir(); + let pi_root = home.join(\".pi/agent/sessions\"); + let codex_root = home.join(\".codex/sessions\"); + let opencode_db = home.join(\".local/share/opencode/opencode.db\"); + + let pi_path = env_path(\"MIGRATE_FIXTURE_PI_SESSION\") + .unwrap_or_else(|| pick_jsonl(&pi_root, &[\"toolCall\", \"toolResult\", \"thinking\"]).expect(\"pick pi session\")); + sanitize_jsonl(&pi_path, &out.join(\"pi_real_sanitized.jsonl\"))?; + + let codex_path = env_path(\"MIGRATE_FIXTURE_CODEX_SESSION\") + .unwrap_or_else(|| pick_jsonl(&codex_root, &[\"function_call\", \"function_call_output\"]).expect(\"pick codex session\")); + sanitize_jsonl(&codex_path, &out.join(\"codex_real_sanitized.jsonl\"))?; + + let opencode_session = std::env::var(\"MIGRATE_FIXTURE_OPENCODE_SESSION\") + .ok() + .unwrap_or_else(|| pick_opencode_session(&opencode_db).expect(\"pick opencode session\")); + sanitize_opencode_sql(&opencode_db, &opencode_session, &out.join(\"opencode_real_sanitized.sql\"))?; + + println!(\"wrote sanitized fixtures to {}\", out.display()); + Ok(()) +} + +fn env_path(name: &str) -> Option<PathBuf> { + std::env::var(name).ok().filter(|s| !s.is_empty()).map(PathBuf::from) +} + +fn pick_jsonl(root: &Path, needles: &[&str]) -> Option<PathBuf> { + let mut stack = vec![root.to_path_buf()]; + while let Some(dir) = stack.pop() { + for entry in std::fs::read_d\n[TRUNCATED]","status":"added"},{"additions":23,"deletions":10,"file":"src/readers/codex.rs","patch":"Index: src/readers/codex.rs =================================================================== --- src/readers/codex.rs +++ src/readers/codex.rs @@ -1,163 +1,176 @@ use std::fs; use std::path::{Path, PathBuf}; use serde_json::Value; use crate::ir::{AgentKind, Event, EventKind, Trace, TraceMeta}; use crate::util::{parse_ts, sha256_hex}; /// Parse a Codex rollout JSONL file (e.g. ~/.codex/sessions/YYYY/MM/DD/rollout-*.jsonl). pub fn read(path: &Path) -> Result<Trace, String> { let raw = fs::read_to_string(path).map_err(|e| format!(\"cannot read {}: {e}\", path.display()))?; let file_hash = sha256_hex(&raw); let mut meta = TraceMeta { source: AgentKind::Codex, session_id: String::new(), file: path.to_string_lossy().into_owned(), cwd: None, title: None, model: None, started_at: None, ended_at: None, source_file_sha256: file_hash.clone(), events_sha256: String::new(), event_count: 0, }; let mut events: Vec<Event> = Vec::new(); for (i, line) in raw.lines().enumerate() { let v: Value = serde_json::from_str(line).map_err(|e| format!(\"{}:{}: bad json: {e}\", path.display(), i + 1))?; let t = v.get(\"type\").and_then(Value::as_str).unwrap_or(\"\"); let ts = v.get(\"timestamp\").and_then(|x| x.as_str()).and_then(parse_ts); match t { \"session_meta\" => { let p = &v[\"payload\"]; meta.session_id = p.get(\"id\").and_then(Value::as_str).unwrap_or_default().to_string(); meta.cwd = p.get(\"cwd\").and_then(Value::as_str).map(String::from); meta.started_at = p .get(\"timestamp\") .and_then(Value::as_str) .and_then(parse_ts) .or(ts); if let Some(p) = p.get(\"model_provider\").and_then(Value::as_str) { meta.model = Some(p.to_string()); } } \"response_item\" => { let p = &v[\"payload\"]; let ptype = p.get(\"type\").and_then(Value::as_str).unwrap_or(\"\"); match ptype { \"message\" => { let text = collect_text(&p[\"content\"]); let role = p.get(\"role\").and_then(Value::as_str).unwrap_or(\"\"); if !text.is_empty() { let ev = match role { \"user\" | \"developer\" => EventKind::UserMessage { text }, _ => EventKind::AssistantMess\n[TRUNCATED]","status":"modified"},{"additions":497,"deletions":0,"file":"tests/fixtures/real/codex_real_sanitized.jsonl","patch":"Index: tests/fixtures/real/codex_real_sanitized.jsonl =================================================================== --- tests/fixtures/real/codex_real_sanitized.jsonl +++ tests/fixtures/real/codex_real_sanitized.jsonl @@ -0,0 +1,497 @@ +{\"payload\":{\"base_instructions\":{\"text\":\"[REDACTED_BASE_INSTRUCTIONS]\"},\"cli_version\":\"0.147.0\",\"context_window\":{\"window_id\":\"019fff07-7215-7d81-83e4-73f00f120637\"},\"cwd\":\"/workspace/project\",\"git\":{\"branch\":\"main\",\"commit_hash\":\"29c944ac74ae60912dd45be56a82ac9a90201dbc\"},\"history_mode\":\"legacy\",\"id\":\"id_0001\",\"model_provider\":\"labforge\",\"originator\":\"t3code_desktop\",\"session_id\":\"id_0001\",\"source\":\"vscode\",\"timestamp\":\"2026-08-14T06:48:25.894Z\"},\"timestamp\":\"2026-08-14T06:48:26.176Z\",\"type\":\"session_meta\"} +{\"payload\":{\"collaboration_mode_kind\":\"default\",\"model_context_window\":258400,\"started_at\":1786690106,\"turn_id\":\"019fff07-732f-7ba0-b97e-29fa31e43271\",\"type\":\"task_started\"},\"timestamp\":\"2026-08-14T06:48:26.176Z\",\"type\":\"event_msg\"} +{\"payload\":{\"content\":[{\"text\":\"<skills_instructions> ## Skills A skill is a set of instructions provided through a `SKILL.md` source. Below is the list of skills that can be used. Each entry includes a name, description, and source locator. `file` locators are on the host filesystem, `environment resource` locators are owned by an execution environment, `orchestrator resource` locators are opaque non-filesystem resources, and `custom resource` locators use their provider''s access mechanism. ### Available skills - imagegen: Generate or edit raster images when the task benefits from AI-created bitmap visuals such as photos, illustrations, textures, sprites, mockups, or transparent-background cutouts. Use when Codex should create a brand-new image, transform an existing image, or derive visual variants from references, and the output should be a bitmap asset rather than repo-native code or vector. Do not use when the task is better handled by editing existing SVG/vector/code-native assets, exten\n[TRUNCATED]","status":"added"},{"additions":785,"deletions":0,"file":"tests/fixtures/real/opencode_real_sanitized.sql","patch":"Index: tests/fixtures/real/opencode_real_sanitized.sql =================================================================== --- tests/fixtures/real/opencode_real_sanitized.sql +++ tests/fixtures/real/opencode_real_sanitized.sql @@ -0,0 +1,785 @@ +INSERT INTO project (id, worktree, name, time_created, time_updated, sandboxes) VALUES (''global'', ''/'', '''', 0, 0, ''[]''); +INSERT INTO session (id, project_id, slug, directory, title, version, time_created, time_updated, agent, model) VALUES (''opencode-real-sanitized'', ''global'', ''sanitized-fixture'', ''/workspace/project'', ''Sanitized OpenCode Fixture'', ''fixture'', 0, 0, ''fixture'', ''{}''); +INSERT INTO message (id, session_id, time_created, time_updated, data) VALUES (''msg_0000'', ''opencode-real-sanitized'', 1786708745826, 1786708745826, ''{\"agent\":\"build\",\"model\":{\"modelID\":\"deepseek-v4-flash\",\"providerID\":\"deepseek\"},\"role\":\"user\",\"summary\":{\"diffs\":[]},\"time\":{\"created\":1786708745826}}''); +INSERT INTO message (id, session_id, time_created, time_updated, data) VALUES (''msg_0001'', ''opencode-real-