INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0157', 'msg_0040', 'opencode-real-sanitized', 1786710031522, 1786710031522, '{"callID":"call_0050","state":{"input":{"content":"use std::fs; use std::path::{Path, PathBuf}; use serde_json::Value; use crate::ir::{AgentKind, Event, EventKind, Trace, TraceMeta}; use crate::util::sha256_hex; /// Parse a Pi Agent session JSONL file (e.g. ~/.pi/agent/sessions/--<dir>--/<ts>_<uuid>.jsonl). pub fn read(path: &Path) -> Result<Trace, String> { let raw = fs::read_to_string(path).map_err(|e| format!(\"cannot read {}: {e}\", path.display()))?; let file_hash = sha256_hex(&raw); let mut meta = TraceMeta { source: AgentKind::Pi, session_id: String::new(), file: path.to_string_lossy().into_owned(), cwd: None, title: None, model: None, started_at: None, ended_at: None, source_file_sha256: file_hash.clone(), events_sha256: String::new(), event_count: 0, }; let mut events: Vec<Event> = Vec::new(); for (i, line) in raw.lines().enumerate() { let v: Value = serde_json::from_str(line).map_err(|e| format!(\"{}:{}: bad json: {e}\", path.display(), i + 1))?; let t = v.get(\"type\").and_then(Value::as_str).unwrap_or(\"\"); let ts = v .get(\"timestamp\") .and_then(Value::as_str) .and_then(crate::util::parse_ts); match t { \"session\" => { meta.session_id = v.get(\"id\").and_then(Value::as_str).unwrap_or_default().to_string(); meta.cwd = v.get(\"cwd\").and_then(Value::as_str).map(String::from); meta.started_at = ts; } \"model_change\" => { let provider = v.get(\"provider\").and_then(Value::as_str).map(String::from); let model = v.get(\"modelId\").and_then(Value::as_str).map(String::from); meta.model = model.clone().or(provider.clone()); events.push(Event { time: ts, kind: EventKind::ModelChange { provider, model }, }); } \"message\" => { let m = &v[\"message\"]; let role = m.get(\"role\").and_then(Value::as_str).unwrap_or(\"\"); let content = m.get(\"content\").and_then(Value::as_array).cloned().unwrap_or_default(); match role { \"user\" => { let text = join_text(&content); if !text.is_empty() { events.push(Event { time: ts.or(m.get(\"timestamp\").and_then(Value::as_i64)), kind: EventKind::UserMessage { text }, }); } } \"assistant\" => { for item in &content\n[TRUNCATED]","filePath":"/home/user/WORKSPACE/migrate/src/readers/pi.rs"},"metadata":{"diagnostics":{},"exists":false,"filepath":"/home/user/WORKSPACE/migrate/src/readers/pi.rs","truncated":false},"output":"Wrote file successfully.","status":"completed","time":{"end":1786710041243,"start":1786710041227},"title":"home/user/WORKSPACE/migrate/src/readers/pi.rs"},"tool":"write","type":"tool"}');
