INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0162', 'msg_0041', 'opencode-real-sanitized', 1786710044833, 1786710044833, '{"callID":"call_0051","state":{"input":{"content":"use std::path::Path; use rusqlite::Connection; use serde_json::Value; use crate::ir::{AgentKind, Event, EventKind, Trace, TraceMeta}; use crate::util::sha256_hex; /// Parse a session from the OpenCode SQLite store (default ~/.local/share/opencode/opencode.db). pub fn read(db_path: &Path, session_id: &str) -> Result<Trace, String> { let conn = Connection::open(db_path).map_err(|e| format!(\"open {}: {e}\", db_path.display()))?; let sess: Option<(String, Option<String>, Option<String>, Option<String>, Option<i64>)> = conn .query_row( \"SELECT id, directory, title, model, time_created FROM session WHERE id = ?1\", [session_id], |r| { Ok(( r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get::<_, Option<i64>>(4)?, )) }, ) .ok(); let (sess_id, directory, title, model, started_at) = match sess { Some(s) => s, None => { return Err(format!( \"session {session_id} not found in {}\", db_path.display() )) } }; let mut raw = String::new(); for row in conn .prepare(\"SELECT data FROM message WHERE session_id = ?1 ORDER BY time_created, id\") .map_err(|e| e.to_string())? .query_map([session_id], |r| r.get::<_, String>(0)) .map_err(|e| e.to_string())? { raw.push_str(&row.map_err(|e| e.to_string())?); raw.push(''\\n''); } let file_hash = sha256_hex(&raw); let mut events: Vec<Event> = Vec::new(); for msg in conn .prepare(\"SELECT id, data, time_created FROM message WHERE session_id = ?1 ORDER BY time_created, id\") .map_err(|e| e.to_string())? .query_map([session_id], |r| { Ok((r.get::<_, String>(0)?, r.get::<_, String>(1)?, r.get::<_, i64>(2)?)) }) .map_err(|e| e.to_string())? { let (msg_id, msg_data, msg_time) = msg.map_err(|e| e.to_string())?; let mv: Value = serde_json::from_str(&msg_data).map_err(|e| format!(\"bad message json: {e}\"))?; let role = mv.get(\"role\").and_then(Value::as_str).unwrap_or(\"\"); // Collect this message''s parts in order. let parts: Vec<(String, i64)> = conn .prepare(\"SELECT data, time_created FROM part WHERE message_id = ?1 ORDER BY time_created, id\") .map_err(|e| e.to_stri\n[TRUNCATED]","filePath":"/home/user/WORKSPACE/migrate/src/readers/opencode.rs"},"metadata":{"diagnostics":{},"exists":false,"filepath":"/home/user/WORKSPACE/migrate/src/readers/opencode.rs","truncated":false},"output":"Wrote file successfully.","status":"completed","time":{"end":1786710053614,"start":1786710053609},"title":"home/user/WORKSPACE/migrate/src/readers/opencode.rs"},"tool":"write","type":"tool"}');
