INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0170', 'msg_0043', 'opencode-real-sanitized', 1786710062282, 1786710062282, '{"callID":"call_0053","state":{"input":{"content":"use std::path::{Path, PathBuf}; use chrono::Utc; use serde::{Deserialize, Serialize}; use crate::ir::{Event, EventKind, Trace}; use crate::util::sha256_hex; #[derive(Debug, Clone, Serialize, Deserialize)] pub struct SourceRef { pub agent: String, pub session_id: String, pub file: String, pub file_sha256: String, pub events_sha256: String, pub event_count: usize, pub exported_at: String, } #[derive(Debug, Clone, Serialize, Deserialize)] pub struct TargetRef { pub agent: String, pub session_id: String, /// Anchor message id: the last message injected by the importer, used to /// detect whether the target agent continued past the seed point. pub anchor_message_id: String, pub injected_at: String, pub events_sha256: String, } #[derive(Debug, Clone, Serialize, Deserialize)] pub struct Manifest { pub version: u32, pub seed_files: Vec<String>, pub source: SourceRef, pub target: Option<TargetRef>, } /// Write seed.json (canonical IR), seed.md (markdown transcript) and /// manifest.json into `out_dir`. Returns the manifest. pub fn write_seed(trace: &Trace, out_dir: &Path) -> Result<Manifest, String> { std::fs::create_dir_all(out_dir).map_err(|e| format!(\"mkdir {}: {e}\", out_dir.display()))?; let seed_json = out_dir.join(\"seed.json\"); let seed_md = out_dir.join(\"seed.md\"); let manifest_path = out_dir.join(\"manifest.json\"); let json_text = serde_json::to_string_pretty(trace).map_err(|e| e.to_string())?; std::fs::write(&seed_json, json_text).map_err(|e| format!(\"write {}: {e}\", seed_json.display()))?; let md = to_markdown(trace); std::fs::write(&seed_md, md).map_err(|e| format!(\"write {}: {e}\", seed_md.display()))?; let manifest = Manifest { version: 1, seed_files: vec![\"seed.json\".into(), \"seed.md\".into()], source: SourceRef { agent: trace.meta.source.as_str().into(), session_id: trace.meta.session_id.clone(), file: trace.meta.file.clone(), file_sha256: trace.meta.source_file_sha256.clone(), events_sha256: trace.meta.events_sha256.clone(), event_count: trace.meta.event_count, \n[TRUNCATED]","filePath":"/home/user/WORKSPACE/migrate/src/export.rs"},"metadata":{"diagnostics":{},"exists":false,"filepath":"/home/user/WORKSPACE/migrate/src/export.rs","truncated":false},"output":"Wrote file successfully.","status":"completed","time":{"end":1786710072192,"start":1786710072186},"title":"home/user/WORKSPACE/migrate/src/export.rs"},"tool":"write","type":"tool"}');
