INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0199', 'msg_0050', 'opencode-real-sanitized', 1786710124127, 1786710124127, '{"callID":"call_0060","state":{"input":{"content":"use std::path::Path; use rusqlite::Connection; use crate::export::Manifest; use crate::ir::AgentKind; use crate::readers; pub struct SourceStatus { pub file_unchanged: bool, pub events_unchanged: bool, pub detail: String, } pub struct TargetStatus { pub session_present: bool, pub anchor_present: bool, pub continued_past_seed: bool, pub extra_messages: usize, pub detail: String, } pub struct StatusReport { pub source: SourceStatus, pub target: TargetStatus, } pub fn check(manifest: &Manifest, opencode_db: &Path) -> Result<StatusReport, String> { let kind = AgentKind::from_str(&manifest.source.agent) .ok_or_else(|| format!(\"unknown agent {}\", manifest.source.agent))?; // --- Source --- let source_detail; let (file_unchanged, events_unchanged) = match kind { AgentKind::Codex | AgentKind::Pi => { let path = Path::new(&manifest.source.file); if !path.exists() { source_detail = format!(\"source file missing: {}\", path.display()); (false, false) } else { let file_hash = crate::util::sha256_file(path)?; let file_unchanged = file_hash == manifest.source.file_sha256; let events_unchanged = recheck_events(kind, &manifest.source.file, &manifest.source.events_sha256); let mut detail = format!(\"source file: {}\", path.display()); if !file_unchanged { detail.push_str(\" [CHANGED]\"); } source_detail = detail; (file_unchanged, events_unchanged) } } AgentKind::OpenCode => { let (db, _sid) = split_db_session(&manifest.source.file); let db = Path::new(db); let hash = opencode_session_hash(db, &manifest.source.session_id)?; let unchanged = hash == manifest.source.events_sha256; let mut detail = format!(\"opencode source: {} ({})\", manifest.source.session_id, db.display()); if !unchanged { detail.push_str(\" [CHANGED]\"); } source_detail = detail; (unchanged, unchanged) } }; // --- Target --- let target_status = match &manifest.target { None => TargetStatus { session_present: false, anchor_present: false, continued_past_seed: false, extra_messages: 0, detail: \"no target seeded yet (run `import\n[TRUNCATED]","filePath":"/home/user/WORKSPACE/migrate/src/sync.rs"},"metadata":{"diagnostics":{},"exists":false,"filepath":"/home/user/WORKSPACE/migrate/src/sync.rs","truncated":false},"output":"Wrote file successfully.","status":"completed","time":{"end":1786710135402,"start":1786710135394},"title":"home/user/WORKSPACE/migrate/src/sync.rs"},"tool":"write","type":"tool"}');
