INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0204', 'msg_0051', 'opencode-real-sanitized', 1786710139194, 1786710139194, '{"callID":"call_0061","state":{"input":{"content":"mod export; mod import; mod ir; mod readers; mod sync; mod util; use std::path::PathBuf; use clap::{Parser, Subcommand}; use ir::AgentKind; #[derive(Parser)] #[command(name = \"migrate\", about = \"Cross coding-agent execution history migration tool\", version)] struct Cli { #[command(subcommand)] command: Command, } #[derive(Subcommand)] enum Command { /// List available sessions of an agent List { agent: String, #[arg(long)] codex_root: Option<PathBuf>, #[arg(long)] pi_root: Option<PathBuf>, #[arg(long)] opencode_db: Option<PathBuf>, }, /// Read an agent session and export a portable seed (seed.json + seed.md + manifest.json) Export { agent: String, session: String, #[arg(short, long)] out: PathBuf, #[arg(long)] codex_root: Option<PathBuf>, #[arg(long)] pi_root: Option<PathBuf>, #[arg(long)] opencode_db: Option<PathBuf>, }, /// Import a seed into a target agent''s native storage Import { agent: String, #[arg(short, long)] seed: PathBuf, #[arg(long)] opencode_db: Option<PathBuf>, }, /// Diff the seed''s source and target sessions against the manifest Status { seed: PathBuf, #[arg(long)] opencode_db: Option<PathBuf>, }, } fn main() { let cli = Cli::parse(); if let Err(e) = run(cli) { eprintln!(\"error: {e}\"); std::process::exit(1); } } fn default_codex_root() -> PathBuf { home_dir().join(\".codex/sessions\") } fn default_pi_root() -> PathBuf { home_dir().join(\".pi/agent/sessions\") } fn default_opencode_db() -> PathBuf { home_dir().join(\".local/share/opencode/opencode.db\") } fn home_dir() -> PathBuf { std::env::var(\"HOME\").map(PathBuf::from).unwrap_or_else(|_| PathBuf::from(\".\")) } fn run(cli: Cli) -> Result<(), String> { match cli.command { Command::List { agent, codex_root, pi_root, opencode_db } => { let kind = parse_agent(&agent)?; match kind { AgentKind::Codex => { let root = codex_root.unwrap_or_else(default_codex_root); for (stem, path) in readers::codex::list_sessions(&root)? { println!(\"{stem}\\t{}\", path.display()); } } AgentKind::Pi => { let root = pi_root.unwrap_or\n[TRUNCATED]","filePath":"/home/user/WORKSPACE/migrate/src/main.rs"},"metadata":{"diagnostics":{},"exists":true,"filepath":"/home/user/WORKSPACE/migrate/src/main.rs","truncated":false},"output":"Wrote file successfully.","status":"completed","time":{"end":1786710149111,"start":1786710149102},"title":"home/user/WORKSPACE/migrate/src/main.rs"},"tool":"write","type":"tool"}');
