INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0392', 'msg_0102', 'opencode-real-sanitized', 1786710386947, 1786710386947, '{"callID":"call_0114","state":{"input":{"content":"use std::path::PathBuf; use migrate::export; use migrate::import; use migrate::ir::EventKind; use migrate::readers; fn fixture(name: &str) -> PathBuf { PathBuf::from(env!(\"CARGO_MANIFEST_DIR\")).join(\"tests/fixtures\").join(name) } #[test] fn codex_reader_extracts_events() { let trace = readers::codex::read(&fixture(\"codex.jsonl\")).expect(\"read codex fixture\"); assert_eq!(trace.meta.session_id, \"codex-sess-1\"); assert_eq!(trace.meta.cwd.as_deref(), Some(\"/tmp/work\")); assert_eq!(trace.meta.source_file_sha256.len(), 64); let types: Vec<&str> = trace .events .iter() .map(|e| match &e.kind { EventKind::UserMessage { .. } => \"user\", EventKind::AssistantMessage { .. } => \"assistant\", EventKind::Reasoning { .. } => \"reasoning\", EventKind::ToolCall { .. } => \"tool_call\", EventKind::ToolResult { .. } => \"tool_result\", EventKind::ModelChange { .. } => \"model_change\", }) .collect(); assert_eq!( types, vec![\"user\", \"assistant\", \"tool_call\", \"tool_result\", \"reasoning\"] ); assert_eq!(trace.meta.event_count, 5); // tool call args preserved verbatim let tool_call = trace .events .iter() .find(|e| matches!(e.kind, EventKind::ToolCall { .. })) .unwrap(); match &tool_call.kind { EventKind::ToolCall { id, name, arguments } => { assert_eq!(id, \"call_1\"); assert_eq!(name, \"bash\"); assert_eq!(arguments, r#\"{\"cmd\":\"ls\"}\"#); } _ => unreachable!(), } } #[test] fn pi_reader_extracts_events() { let trace = readers::pi::read(&fixture(\"pi.jsonl\")).expect(\"read pi fixture\"); assert_eq!(trace.meta.session_id, \"pi-sess-1\"); assert_eq!(trace.meta.cwd.as_deref(), Some(\"/tmp/work\")); let types: Vec<&str> = trace .events .iter() .map(|e| match &e.kind { EventKind::UserMessage { .. } => \"user\", EventKind::AssistantMessage { .. } => \"assistant\", EventKind::Reasoning { .. } => \"reasoning\", EventKind::ToolCall { .. } => \"tool_call\", EventKind::ToolResult { .. } => \"tool_result\", EventKind::ModelChange { .. } => \"model_change\", }) .collect(); assert_eq!( types, vec![\"model_change\", \"user\", \"reasoning\", \"assi\n[TRUNCATED]","filePath":"/home/user/WORKSPACE/migrate/tests/migrate.rs"},"metadata":{"diagnostics":{},"exists":false,"filepath":"/home/user/WORKSPACE/migrate/tests/migrate.rs","truncated":false},"output":"Wrote file successfully.","status":"completed","time":{"end":1786710395922,"start":1786710395916},"title":"home/user/WORKSPACE/migrate/tests/migrate.rs"},"tool":"write","type":"tool"}');
