INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0460', 'msg_0116', 'opencode-real-sanitized', 1786752967310, 1786752967310, '{"text":"**Implementing seed directory functions** I need to implement `resolve_seed_dir` and `latest_seed_dir` in `main.rs`, and also adjust the status to use default. First, I’ll make sure to use `Path` and `PathBuf`. It seems logical to patch `main.rs` by adding this helper function after loading the trace. I might want to fully qualify `std::time::SystemTime` for clarity. The helper functions should manage seed directories, checking for the existence of necessary files and ensuring error handling when the base directory doesn’t exist.","time":{"end":1786752967738,"start":1786752967310},"type":"reasoning"}');
INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0461', 'msg_0116', 'opencode-real-sanitized', 1786752967740, 1786752967740, '{"text":"Next I’m wiring the default seed resolution so `import/status` can work without `--seed` when a configured/latest seed is available.","time":{"end":1786752970754,"start":1786752967740},"type":"text"}');
INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0462', 'msg_0116', 'opencode-real-sanitized', 1786752970720, 1786752970720, '{"callID":"call_0131","state":{"input":{"patchText":"*** Begin Patch *** Update File: /home/user/WORKSPACE/migrate/src/main.rs @@ fn load_trace(seed_dir: &Path) -> Result<ir::Trace, String> { @@ serde_json::from_str(&raw).map_err(|e| format!(\"parse {}: {e}\", p.display())) } + +fn resolve_seed_dir(seed: Option<PathBuf>) -> Result<PathBuf, String> { + if let Some(seed) = seed { + return Ok(seed); + } + + let base = config::default_seed_dir(); + if base.join(\"seed.json\").exists() && base.join(\"manifest.json\").exists() { + return Ok(base); + } + + latest_seed_dir(&base).ok_or_else(|| { + format!( + \"no seed specified and no seed found under {} (set MIGRATE_SEED_DIR, ~/.config/migrate/config.json, or pass --seed)\", + base.display() + ) + }) +} + +fn latest_seed_dir(base: &Path) -> Option<PathBuf> { + let mut best: Option<(std::time::SystemTime, PathBuf)> = None; + walk_seed_dirs(base, &mut best); + best.map(|(_, p)| p) +} + +fn walk_seed_dirs(dir: &Path, best: &mut Option<(std::time::SystemTime, PathBuf)>) { + let entries = match std::fs::read_dir(dir) { + Ok(entries) => entries, + Err(_) => return, + }; + for entry in entries.flatten() { + let path = entry.path(); + if path.is_dir() { + let manifest = path.join(\"manifest.json\"); + if manifest.exists() { + if let Ok(modified) = manifest.metadata().and_then(|m| m.modified()) { + match best { + Some((best_time, _)) if *best_time >= modified => {} + _ => *best = Some((modified, path.clone())), + } + } + } + walk_seed_dirs(&path, best); + } + } +} fn yesno(b: bool) -> &''static str { *** End Patch"},"metadata":{"diagnostics":{},"diff":"Index: /home/user/WORKSPACE/migrate/src/main.rs =================================================================== --- /home/user/WORKSPACE/migrate/src/main.rs +++ /home/user/WORKSPACE/migrate/src/main.rs @@ -189,8 