 resolve_seed_dir(seed: Option<PathBuf>) -> Result<PathBuf, String> { + if let Some(seed) = seed { + return Ok(seed); + } + + let base = config::default_seed_dir(); + if base.join(\"seed.json\").exists() && base.join(\"manifest.json\").exists() { + return Ok(base); + } + + latest_seed_dir(&base).ok_or_else(|| { + format!( + \"no seed specified and no seed found under {} (set MIGRATE_SEED_DIR, ~/.config/migrate/config.json, or pass --seed)\", + base.display() + ) + }) +} + +fn latest_seed_dir(base: &Path) -> Option<PathBuf> { + let mut best: Option<(std::time::SystemTime, PathBuf)> = None; + walk_seed_dirs(base, &mut best); + best.map(|(_, p)| p) +} + +fn walk_seed_dirs(dir: &Path, best: &mut Option<(std::time::SystemTime, PathBuf)>) { + let entries = match std::fs::read_dir(dir) { + Ok(entries) => entries, + Err(_) => return, + }; + for entry in entries.flatten() { + let path = entry.path(); + if path.is_dir() { + let manifest = path.join(\"manifest.json\"); + if manifest.exists() { + if let Ok(modified) = manifest.metadata().and_then(|m| m.modified()) { + match best { + Some((best_time, _)) if *best_time >= modified => {} + _ => *best = Some((modified, path.clone())), + } + } + } + walk_seed_dirs(&path, best); + } + } +} + fn yesno(b: bool) -> &''static str { if b { \"yes\" } else {","relativePath":"src/main.rs","type":"update"}],"truncated":false},"output":"Success. Updated the following files: M src/main.rs","status":"completed","time":{"end":1786752970733,"start":1786752970727},"title":"Success. Updated the following files: M src/main.rs"},"tool":"apply_patch","type":"tool"}');
