INSERT INTO part (id, message_id, session_id, time_created, time_updated, data) VALUES ('prt_0553', 'msg_0136', 'opencode-real-sanitized', 1786753841316, 1786753841316, '{"text":"现在有使用真实的 pi session 和 Open Code session 进行转换测试吗？也不一定是就是这两个 session，也可能是其他 session 进行转换，都有测试吗？","type":"text"}');
